BEGIN;
SET LOCAL lock_timeout='5s'; SET LOCAL statement_timeout='60s';
LOCK TABLE public.questions IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE swsi_before ON COMMIT DROP AS SELECT id, to_jsonb(q) AS row FROM public.questions q;
CREATE TEMP TABLE swsi_batch(id text primary key, status text, note text, url text) ON COMMIT DROP;
INSERT INTO swsi_batch VALUES ('SP104-1-24','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2015-02-07。本題考家庭暴力防治法第50條（責任通報，至遲不得逾二十四小時）。2015-02-04（考試前三日）及 2023-12-06 修正調整通報人員（增列教保服務人員、移民業務人員等），學校教師（教育人員）、社會工作人員、保育人員仍為責任通報人員，村（里）長仍非責任通報人員。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050071'),('SP104-2-25','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2015-07-25。本題考家庭暴力防治法第3條（家庭成員範圍以四親等為準），本題官方一律給分；2023-12-06 修正調整第3條各款，不影響本題計分。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050071'),('SP104-2-26','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考家庭暴力防治法第36條之1（偵查中得陪同被害人之人員），最後修正公布日：第36條之1 2015-02-04，本題考試日 2015-07-25 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050071'),('SP104-2-38','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2015-07-25。本題考家庭暴力防治法第15條（通常保護令有效期間二年以下）、第16條（暫時及緊急保護令得不經審理）、第18條（核發後二十四小時內發送）、第20條（抗告不停止執行）；2023-12-06 修正僅調整延長程序及得核發款項，選項(A)「一年以下」仍錯誤。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050071'),('SP105-1-17','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2016-01-30。本題考家庭暴力防治法第3條（家庭成員以四親等為準）、第5條（每四年調查分析，2015-02-04 後未修正）、第13條（不得調解或和解）、第16條（通常保護令須經審理）；2023-12-06 修正未改變各選項正誤。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050071'),('SP105-1-18','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2016-01-30。本題考家庭暴力防治法第14條（目睹家庭暴力兒童及少年得列為保護令保護對象，2015-02-04 增訂）；2023-12-06 修正增列命令款項，選項(C)「無法為目睹兒少申請保護令」仍錯誤。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050071'),('SP105-2-21','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2016-07-23。本題考家庭暴力防治法第50條（至遲不得逾二十四小時通報）、第52條（醫療機構不得無故拒絕診療及開立驗傷診斷書，2007-03-28 後未修正）；選項(B)「四十八小時」仍錯誤。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050071'),('SP105-2-36','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2016-07-23。本題考家庭暴力防治法第15條（有效期間二年以下、每次延長二年以下）、第16條（暫時保護令得依聲請或依職權核發、暫時及緊急保護令得不經審理）；2023-12-06 修正調整延長程序及得核發之款項，各選項正誤不變。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050071'),('SP106-1-05','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2017-02-18。本題考家庭暴力防治法第63條之1（被害人年滿十六歲，遭受未同居親密伴侶不法侵害者準用保護令規定）；2023-12-06 修正僅調整準用條文，年齡要件未變。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050071'),('SP106-1-06','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2017-02-18。本題考家庭暴力防治法第15條（通常保護令有效期間二年以下、每次延長二年以下，檢察官、警察機關或主管機關得聲請延長）；2023-12-06 修正調整延長程序（裁定前原保護令不失效），有效期間與延長期間未變。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050071'),('SP106-1-15','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2017-02-18。本題考家庭暴力防治法第10條（被害人不得自行聲請緊急保護令；未成年人、身心障礙者等得由法定代理人、三親等以內血親或姻親聲請，2008-01-09 後未修正）、第16條（緊急保護令四小時內核發、得不經審理）；2023-12-06 修正不影響各選項正誤。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050071'),('SP106-1-19','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2017-02-18。本題考家庭暴力防治法第3條（家庭成員）；考試時旁系血親或姻親以四親等為限，2023-12-06 修正調整各款仍以四親等為準，「五親等」仍非家庭成員。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050071'),('SP107-1-27','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考家庭暴力防治法第13條（保護令審理程序與不得調解或和解），最後修正公布日：第13條 2007-03-28，本題考試日 2018-02-03 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050071'),('SP107-2-07','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2018-07-28。本題考家庭暴力防治法第12條（書面聲請，緊急保護令不在此限）、第15條（每次延長二年以下，無次數限制）、第16條、第18條；2023-12-06 修正調整延長程序，選項(B)「延長一年並以一次為限」仍錯誤。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050071'),('SP107-2-30','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考家庭暴力防治法第29條（家庭暴力罪之逕行拘提），最後修正公布日：第29條 2007-03-28，本題考試日 2018-07-28 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050071'),('SP108-1-23','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2019-01-19。本題考家庭暴力防治法第3條（家庭成員）；考試時旁系血親或姻親以四親等為限，2023-12-06 修正調整各款仍以四親等為準，「五親等」仍非家庭成員。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050071'),('SP108-1-24','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2019-01-19。本題考家庭暴力防治法第14條、第16條。考試時暫時保護令及緊急保護令僅得核發第14條第1項第1款至第6款、第12款及第13款之命令，不含第10款「完成加害人處遇計畫」（官方答案C）；2023-12-06 修正後，聲請人為直轄市、縣（市）主管機關者，法院並得核發第10款之暫時保護令或緊急保護令，選項(C)已非必然錯誤。本題官方答案依考試時條文判定；作答時請以現行條文為準。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050071'),('SP108-2-28','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2019-07-27。本題考家庭暴力防治法第16條（暫時及緊急保護令得不經審理、視為已聲請通常保護令；緊急保護令四小時內核發）；2023-12-06 修正調整得核發之款項，選項(C)「均應於24小時內核發」仍錯誤。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050071'),('SP109-1-25','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考家庭暴力防治法第28條（外國法院保護令之承認與執行），最後修正公布日：第28條 2007-03-28，本題考試日 2020-02-15 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050071'),('SP109-2-27','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2020-08-01。本題考家庭暴力防治法第54條。考試時規定由「中央衛生主管機關」訂定家庭暴力加害人處遇計畫規範（官方答案B）；2023-12-06 修正改為「中央主管機關」，選項(B)用語已與現行條文不同。本題官方答案依考試時條文判定；作答時請以現行條文為準。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050071'),('SP109-2-28','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2020-08-01。本題考家庭暴力防治法第58條（被害人補助項目）；2021-01-27 修正僅將申請創業貸款之年齡改為成年，補助項目未變，選項(D)「職業訓練津貼」仍非法定補助。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050071'),('SP110-1-27','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2021-02-06。本題考家庭暴力防治法第15條（通常保護令有效期間二年以下、每次延長二年以下，檢察官、警察機關或主管機關得聲請延長）；2023-12-06 修正調整延長程序（裁定前原保護令不失效），有效期間與延長期間未變。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050071'),('SP110-1-28','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2021-02-06。本題考家庭暴力防治法第13條（社工人員得陪同在場）、第45條（會面交往）、第50條（責任通報）；社會工作人員不負責執行保護令之給付命令，2023-12-06 修正不影響本題。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050071'),('SP110-2-27','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2021-08-21。本題考家庭暴力防治法第63條之1（被害人年滿十六歲，遭受未同居親密伴侶不法侵害者準用保護令規定）；2023-12-06 修正僅調整準用條文，年齡要件未變。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050071'),('SP111-1-26','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考家庭暴力防治法第9條（民事保護令種類），最後修正公布日：第9條 2007-03-28，本題考試日 2022-02-19 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050071'),('SP111-1-28','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考家庭暴力防治法第45條（會面交往命令），最後修正公布日：第45條 2007-03-28，本題考試日 2022-02-19 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050071'),('SP111-1-29','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考家庭暴力防治法第58條（被害人補助項目），最後修正公布日：第58條 2021-01-27，本題考試日 2022-02-19 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050071'),('SP111-1-30','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2022-02-19。本題考家庭暴力防治法第60條（高級中等以下學校每學年應有四小時以上家庭暴力防治課程）；2023-12-06 修正增列學校應實施防治課程或活動，四小